#!/usr/bin/env python3
"""Mini generador de .docx (OOXML) con la biblioteca estándar."""
import re
import struct
import zipfile
from xml.sax.saxutils import escape

NAVY = "241A61"
GRAY = "595959"
LIGHT = "F3F2F8"
BORDER = "BFBFBF"
TBD_FG = "9C4A00"
TBD_BG = "FFF2CC"
PAGE_W, PAGE_H = 12240, 15840
MARGIN_LR, MARGIN_T, MARGIN_B = 1418, 1418, 1276
CONTENT_W = PAGE_W - 2 * MARGIN_LR  # 9404

NS = (
    'xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" '
    'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" '
    'xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" '
    'xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" '
    'xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"'
)


def esc(t):
    return escape(t, {'"': "&quot;"})


def png_size(path):
    with open(path, "rb") as f:
        head = f.read(24)
    w, h = struct.unpack(">II", head[16:24])
    return w, h


class Doc:
    def __init__(self):
        self.body = []
        self.rels = []  # (rid, type, target, external)
        self.media = []  # (name, path)
        self.headings = []  # (level, text, bookmark)
        self._rid = 10
        self._bm = 0
        self._img = 0
        self.fig = 0
        self.tab = 0
        self.toc_pages = {}

    # ------------------------------------------------------------ utilidades
    def new_rid(self):
        self._rid += 1
        return f"rId{self._rid}"

    def link_rel(self, url):
        for rid, typ, target, ext in self.rels:
            if target == url and ext:
                return rid
        rid = self.new_rid()
        self.rels.append((rid, "hyperlink", url, True))
        return rid

    @staticmethod
    def rpr(bold=False, italic=False, color=None, size=None, shade=None, style=None, caps=False, spacing=None):
        x = ""
        if style:
            x += f'<w:rStyle w:val="{style}"/>'
        if bold:
            x += "<w:b/><w:bCs/>"
        if italic:
            x += "<w:i/><w:iCs/>"
        if caps:
            x += "<w:caps/>"
        if color:
            x += f'<w:color w:val="{color}"/>'
        if spacing:
            x += f'<w:spacing w:val="{spacing}"/>'
        if size:
            x += f'<w:sz w:val="{size}"/><w:szCs w:val="{size}"/>'
        if shade:
            x += f'<w:shd w:val="clear" w:color="auto" w:fill="{shade}"/>'
        return f"<w:rPr>{x}</w:rPr>" if x else ""

    def run(self, text, **kw):
        parts = text.split("\t")
        out = []
        for i, part in enumerate(parts):
            if i:
                out.append(f"<w:r>{self.rpr(**kw)}<w:tab/></w:r>")
            if part:
                out.append(f'<w:r>{self.rpr(**kw)}<w:t xml:space="preserve">{esc(part)}</w:t></w:r>')
        return "".join(out)

    TOKEN = re.compile(r"(\*\*.+?\*\*|__.+?__|\[POR DEFINIR\]|\[Completar\]|https?://[^\s)]+)")

    def runs(self, text, bold=False, italic=False, color=None, size=None):
        out = []
        for tok in self.TOKEN.split(text):
            if not tok:
                continue
            if tok.startswith("**") and tok.endswith("**"):
                out.append(self.runs(tok[2:-2], bold=True, italic=italic, color=color, size=size))
            elif tok.startswith("__") and tok.endswith("__"):
                out.append(self.runs(tok[2:-2], bold=bold, italic=True, color=color, size=size))
            elif tok == "[POR DEFINIR]":
                out.append(self.run(tok, bold=True, color=TBD_FG, shade=TBD_BG, size=size))
            elif tok == "[Completar]":
                out.append(self.run(tok, italic=True, color="808080", size=size))
            elif tok.startswith("http"):
                rid = self.link_rel(tok)
                out.append(
                    f'<w:hyperlink r:id="{rid}" w:history="1">{self.run(tok, style="Hyperlink", size=size)}</w:hyperlink>'
                )
            else:
                out.append(self.run(tok, bold=bold, italic=italic, color=color, size=size))
        return "".join(out)

    @staticmethod
    def ppr(style=None, align=None, before=None, after=None, keep_next=False, num=None, ind=None, shade=None,
            page_break=False, tabs=None, line=None, keep_lines=False, border_bottom=None):
        x = ""
        if style:
            x += f'<w:pStyle w:val="{style}"/>'
        if keep_next:
            x += "<w:keepNext/>"
        if keep_lines:
            x += "<w:keepLines/>"
        if page_break:
            x += "<w:pageBreakBefore/>"
        if num:
            x += f'<w:numPr><w:ilvl w:val="{num[1]}"/><w:numId w:val="{num[0]}"/></w:numPr>'
        if border_bottom:
            x += f'<w:pBdr><w:bottom w:val="single" w:sz="{border_bottom[0]}" w:space="4" w:color="{border_bottom[1]}"/></w:pBdr>'
        if shade:
            x += f'<w:shd w:val="clear" w:color="auto" w:fill="{shade}"/>'
        if tabs:
            x += "<w:tabs>" + "".join(f'<w:tab w:val="{v}" w:leader="{l}" w:pos="{p}"/>' for v, l, p in tabs) + "</w:tabs>"
        if before is not None or after is not None or line is not None:
            s = ""
            if before is not None:
                s += f' w:before="{before}"'
            if after is not None:
                s += f' w:after="{after}"'
            if line is not None:
                s += f' w:line="{line}" w:lineRule="auto"'
            x += f"<w:spacing{s}/>"
        if ind:
            x += "<w:ind " + " ".join(f'w:{k}="{v}"' for k, v in ind.items()) + "/>"
        if align:
            x += f'<w:jc w:val="{align}"/>'
        return f"<w:pPr>{x}</w:pPr>" if x else ""

    def para_xml(self, text="", style=None, **kw):
        rk = {k: kw.pop(k) for k in ("bold", "italic", "color", "size") if k in kw}
        return f"<w:p>{self.ppr(style=style, **kw)}{self.runs(text, **rk) if text else ''}</w:p>"

    # ------------------------------------------------------------ bloques
    def p(self, text="", style=None, **kw):
        self.body.append(self.para_xml(text, style, **kw))

    def bullets(self, items, level=0):
        for it in items:
            if isinstance(it, list):
                self.bullets(it, level + 1)
            else:
                self.body.append(self.para_xml(it, "ListParagraph", num=(1, level)))

    def numbered(self, items):
        for it in items:
            self.body.append(self.para_xml(it, "ListParagraph", num=(3, 0)))

    def note(self, text, label="Nota"):
        self.body.append(
            f"<w:p>{self.ppr(style='Note')}{self.run(label + ': ', bold=True, color=NAVY)}{self.runs(text)}</w:p>"
        )

    def page_break(self):
        self.body.append('<w:p><w:r><w:br w:type="page"/></w:r></w:p>')

    def heading(self, level, text, toc=True):
        self._bm += 1
        bm = f"_Toc{100000 + self._bm}"
        if toc:
            self.headings.append((level, text, bm))
        self.body.append(
            f'<w:p>{self.ppr(style=f"Heading{level}")}'
            f'<w:bookmarkStart w:id="{self._bm}" w:name="{bm}"/>{self.run(text)}<w:bookmarkEnd w:id="{self._bm}"/></w:p>'
        )

    def caption(self, kind, text):
        if kind == "Figura":
            self.fig += 1
            n = self.fig
        else:
            self.tab += 1
            n = self.tab
        self.body.append(
            f'<w:p>{self.ppr(style="Caption", keep_next=(kind == "Tabla"))}'
            f'{self.run(f"{kind} {n}. ", bold=True, color=NAVY, size=18)}{self.runs(text, size=18)}</w:p>'
        )
        return n

    def image(self, path, width_in, alt):
        self._img += 1
        name = f"image{self._img}.png"
        rid = self.new_rid()
        self.rels.append((rid, "image", f"media/{name}", False))
        self.media.append((name, path))
        pw, ph = png_size(path)
        cx = int(width_in * 914400)
        cy = int(cx * ph / pw)
        n = self._img
        self.body.append(
            f'<w:p>{self.ppr(align="center", before=120, after=60, keep_next=True)}<w:r><w:drawing>'
            f'<wp:inline distT="0" distB="0" distL="0" distR="0"><wp:extent cx="{cx}" cy="{cy}"/>'
            f'<wp:docPr id="{n}" name="Figura {n}" descr="{esc(alt)}"/>'
            '<wp:cNvGraphicFramePr><a:graphicFrameLocks noChangeAspect="1"/></wp:cNvGraphicFramePr>'
            '<a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic>'
            f'<pic:nvPicPr><pic:cNvPr id="{n}" name="{name}" descr="{esc(alt)}"/><pic:cNvPicPr/></pic:nvPicPr>'
            f'<pic:blipFill><a:blip r:embed="{rid}"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill>'
            f'<pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="{cx}" cy="{cy}"/></a:xfrm>'
            '<a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic>'
            "</wp:inline></w:drawing></w:r></w:p>"
        )

    def cell_paras(self, content, header=False, align=None):
        items = content if isinstance(content, list) else [content]
        out = []
        for it in items:
            if header:
                out.append(
                    f'<w:p>{self.ppr(style="TableText", align=align)}{self.runs(it, bold=True, color="FFFFFF")}</w:p>'
                )
            elif isinstance(it, str) and it.startswith("- "):
                out.append(f'<w:p>{self.ppr(style="TableText", num=(2, 0))}{self.runs(it[2:])}</w:p>')
            else:
                out.append(f'<w:p>{self.ppr(style="TableText", align=align)}{self.runs(it)}</w:p>')
        return "".join(out) or '<w:p><w:pPr><w:pStyle w:val="TableText"/></w:pPr></w:p>'

    def table(self, widths, header, rows, first_col_shade=False, banding=True, header_row=True, min_row_h=None):
        assert sum(widths) == CONTENT_W, (sum(widths), header)
        bd = "".join(
            f'<w:{s} w:val="single" w:sz="4" w:space="0" w:color="{BORDER}"/>'
            for s in ("top", "left", "bottom", "right", "insideH", "insideV")
        )
        x = [
            "<w:tbl><w:tblPr>"
            f'<w:tblW w:w="{CONTENT_W}" w:type="dxa"/><w:tblLayout w:type="fixed"/>'
            f"<w:tblBorders>{bd}</w:tblBorders>"
            '<w:tblCellMar><w:top w:w="45" w:type="dxa"/><w:left w:w="90" w:type="dxa"/>'
            '<w:bottom w:w="45" w:type="dxa"/><w:right w:w="90" w:type="dxa"/></w:tblCellMar>'
            '<w:tblLook w:val="04A0" w:firstRow="1" w:lastRow="0" w:firstColumn="1" w:lastColumn="0" w:noHBand="0" w:noVBand="1"/>'
            "</w:tblPr><w:tblGrid>" + "".join(f'<w:gridCol w:w="{w}"/>' for w in widths) + "</w:tblGrid>"
        ]
        if header_row and header:
            x.append('<w:tr><w:trPr><w:cantSplit/><w:tblHeader/></w:trPr>')
            for w, h in zip(widths, header):
                x.append(
                    f'<w:tc><w:tcPr><w:tcW w:w="{w}" w:type="dxa"/>'
                    f'<w:shd w:val="clear" w:color="auto" w:fill="{NAVY}"/><w:vAlign w:val="center"/></w:tcPr>'
                    f"{self.cell_paras(h, header=True)}</w:tc>"
                )
            x.append("</w:tr>")
        for i, row in enumerate(rows):
            trpr = "<w:cantSplit/>"
            if min_row_h:
                trpr += f'<w:trHeight w:val="{min_row_h}"/>'
            x.append(f"<w:tr><w:trPr>{trpr}</w:trPr>")
            for j, (w, c) in enumerate(zip(widths, row)):
                fill = None
                if first_col_shade and j == 0:
                    fill = LIGHT
                elif banding and i % 2 == 1:
                    fill = "FAFAFC"
                shd = f'<w:shd w:val="clear" w:color="auto" w:fill="{fill}"/>' if fill else ""
                content = c
                if first_col_shade and j == 0 and isinstance(c, str):
                    content = f"**{c}**" if c and not c.startswith("**") else c
                x.append(f'<w:tc><w:tcPr><w:tcW w:w="{w}" w:type="dxa"/>{shd}</w:tcPr>{self.cell_paras(content)}</w:tc>')
            x.append("</w:tr>")
        x.append("</w:tbl>")
        self.body.append("".join(x))
        self.body.append('<w:p><w:pPr><w:spacing w:before="0" w:after="60"/></w:pPr></w:p>')

    # ------------------------------------------------------------ índice
    TOC_MARK = "<!--TOC-->"

    def toc_placeholder(self):
        self.body.append(self.TOC_MARK)

    def toc_xml(self):
        out = []
        n = len(self.headings)
        for i, (lvl, text, bm) in enumerate(self.headings):
            if lvl > 3:
                continue
            page = self.toc_pages.get(bm, "")
            begin = ""
            if i == 0:
                begin = (
                    '<w:r><w:fldChar w:fldCharType="begin"/></w:r>'
                    '<w:r><w:instrText xml:space="preserve"> TOC \\o "1-3" \\h \\z \\u </w:instrText></w:r>'
                    '<w:r><w:fldChar w:fldCharType="separate"/></w:r>'
                )
            end = '<w:r><w:fldChar w:fldCharType="end"/></w:r>' if i == n - 1 else ""
            out.append(
                f'<w:p>{self.ppr(style=f"TOC{lvl}")}{begin}'
                f'<w:hyperlink w:anchor="{bm}" w:history="1">{self.run(text)}'
                f'<w:r><w:tab/></w:r><w:r><w:t>{page}</w:t></w:r></w:hyperlink>{end}</w:p>'
            )
        return "".join(out)

    # ------------------------------------------------------------ empaquetado
    def save(self, path, header_text, footer_left, title):
        body = "".join(self.body).replace(self.TOC_MARK, self.toc_xml())
        sect = (
            "<w:sectPr>"
            '<w:headerReference w:type="default" r:id="rId3"/><w:headerReference w:type="first" r:id="rId4"/>'
            '<w:footerReference w:type="default" r:id="rId5"/><w:footerReference w:type="first" r:id="rId6"/>'
            f'<w:pgSz w:w="{PAGE_W}" w:h="{PAGE_H}"/>'
            f'<w:pgMar w:top="{MARGIN_T}" w:right="{MARGIN_LR}" w:bottom="{MARGIN_B}" w:left="{MARGIN_LR}" '
            'w:header="708" w:footer="567" w:gutter="0"/><w:titlePg/></w:sectPr>'
        )
        document = (
            f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document {NS}><w:body>{body}{sect}</w:body></w:document>'
        )
        tab_right = CONTENT_W
        header = (
            f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:hdr {NS}>'
            f'<w:p>{self.ppr(style="Header", align="right", border_bottom=(4, BORDER))}{self.run(header_text, color=GRAY, size=16)}</w:p></w:hdr>'
        )
        footer = (
            f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:ftr {NS}>'
            f'<w:p>{self.ppr(style="Footer", tabs=[("right", "none", tab_right)])}'
            f"{self.run(footer_left, color=GRAY, size=16)}{self.run(chr(9), size=16)}"
            f'{self.run("Página ", color=GRAY, size=16)}'
